--! @file v3/scalars/bigint/bigint_types.sql
--! @brief Encrypted-domain types for bigint.

DO $$
BEGIN
  --! @brief Encrypted domain public.eql_v4_bigint.
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'eql_v4_bigint' AND typnamespace = 'public'::regnamespace
  ) THEN
    CREATE DOMAIN public.eql_v4_bigint AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'c'
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN public.eql_v4_bigint IS 'EQL encrypted bigint (storage only)';

  --! @brief Encrypted domain public.eql_v4_bigint_eq.
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'eql_v4_bigint_eq' AND typnamespace = 'public'::regnamespace
  ) THEN
    CREATE DOMAIN public.eql_v4_bigint_eq AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'c'
        AND VALUE ? 'hm'
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN public.eql_v4_bigint_eq IS 'EQL encrypted bigint (equality)';

  --! @brief Encrypted domain public.eql_v4_bigint_ord_ore.
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'eql_v4_bigint_ord_ore' AND typnamespace = 'public'::regnamespace
  ) THEN
    CREATE DOMAIN public.eql_v4_bigint_ord_ore AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'c'
        AND VALUE ? 'ob'
        AND jsonb_typeof(VALUE -> 'ob') = 'string'
        AND left(VALUE ->> 'ob', 4) IN ('0202', '0203')
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN public.eql_v4_bigint_ord_ore IS 'EQL encrypted bigint (equality, ordering)';

  --! @brief Encrypted domain public.eql_v4_bigint_ord.
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'eql_v4_bigint_ord' AND typnamespace = 'public'::regnamespace
  ) THEN
    CREATE DOMAIN public.eql_v4_bigint_ord AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'c'
        AND VALUE ? 'op'
        AND jsonb_typeof(VALUE -> 'op') = 'string'
        AND left(VALUE ->> 'op', 2) IN ('00', '01')
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN public.eql_v4_bigint_ord IS 'EQL encrypted bigint (equality, ordering)';

  --! @brief Encrypted domain public.eql_v4_bigint_ord_ope.
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'eql_v4_bigint_ord_ope' AND typnamespace = 'public'::regnamespace
  ) THEN
    CREATE DOMAIN public.eql_v4_bigint_ord_ope AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'c'
        AND VALUE ? 'op'
        AND jsonb_typeof(VALUE -> 'op') = 'string'
        AND left(VALUE ->> 'op', 2) IN ('00', '01')
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN public.eql_v4_bigint_ord_ope IS 'EQL encrypted bigint (equality, ordering)';
END
$$;
-- AUTOMATICALLY GENERATED FILE.

--! @file v3/scalars/bigint/query_bigint_types.sql
--! @brief Query-operand domains for bigint (index-terms-only, no ciphertext).
--! @note Query-operand domains live in `eql_v4` (not `public`): they are
--!       never valid column types, so they don't belong in the column-type
--!       namespace, and dropping the EQL-owned schema can never drop an
--!       application column.
--! @note Cast a query operand explicitly to its `query_` domain in a predicate
--!       (e.g. `WHERE col = $1::eql_v4.query_bigint_eq`). A bare,
--!       uncast literal RHS is ambiguous between the `query_` and `jsonb`
--!       operator overloads and will not resolve.

DO $$
BEGIN
