--! @file v3/scalars/integer/query_integer_types.sql
--! @brief Query-operand domains for integer (index-terms-only, no ciphertext).
--! @note Query-operand domains live in `eql_v4` (not `public`): they are
--!       never valid column types, so they don't belong in the column-type
--!       namespace, and dropping the EQL-owned schema can never drop an
--!       application column.
--! @note Cast a query operand explicitly to its `query_` domain in a predicate
--!       (e.g. `WHERE col = $1::eql_v4.query_integer_eq`). A bare,
--!       uncast literal RHS is ambiguous between the `query_` and `jsonb`
--!       operator overloads and will not resolve.

DO $$
BEGIN
  --! @brief Query-operand domain eql_v4.query_integer_eq (term-only; no `c`).
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'query_integer_eq' AND typnamespace = 'eql_v4'::regnamespace
  ) THEN
    CREATE DOMAIN eql_v4.query_integer_eq AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'hm'
        AND NOT (VALUE ? 'c')
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN eql_v4.query_integer_eq IS 'EQL integer query operand (equality)';

  --! @brief Query-operand domain eql_v4.query_integer_ord_ore (term-only; no `c`).
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'query_integer_ord_ore' AND typnamespace = 'eql_v4'::regnamespace
  ) THEN
    CREATE DOMAIN eql_v4.query_integer_ord_ore AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'ob'
        AND NOT (VALUE ? 'c')
        AND jsonb_typeof(VALUE -> 'ob') = 'string'
        AND left(VALUE ->> 'ob', 4) IN ('0202', '0203')
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN eql_v4.query_integer_ord_ore IS 'EQL integer query operand (equality, ordering)';

  --! @brief Query-operand domain eql_v4.query_integer_ord (term-only; no `c`).
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'query_integer_ord' AND typnamespace = 'eql_v4'::regnamespace
  ) THEN
    CREATE DOMAIN eql_v4.query_integer_ord AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'op'
        AND NOT (VALUE ? 'c')
        AND jsonb_typeof(VALUE -> 'op') = 'string'
        AND left(VALUE ->> 'op', 2) IN ('00', '01')
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN eql_v4.query_integer_ord IS 'EQL integer query operand (equality, ordering)';

  --! @brief Query-operand domain eql_v4.query_integer_ord_ope (term-only; no `c`).
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'query_integer_ord_ope' AND typnamespace = 'eql_v4'::regnamespace
  ) THEN
    CREATE DOMAIN eql_v4.query_integer_ord_ope AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'op'
        AND NOT (VALUE ? 'c')
        AND jsonb_typeof(VALUE -> 'op') = 'string'
        AND left(VALUE ->> 'op', 2) IN ('00', '01')
        AND VALUE->>'v' = '4'
