BEGIN
  --! @brief Query-operand domain eql_v4.query_smallint_eq (term-only; no `c`).
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'query_smallint_eq' AND typnamespace = 'eql_v4'::regnamespace
  ) THEN
    CREATE DOMAIN eql_v4.query_smallint_eq AS jsonb
      CHECK (
        jsonb_typeof(VALUE) = 'object'
        AND VALUE ? 'v'
        AND VALUE ? 'i'
        AND VALUE ? 'hm'
        AND NOT (VALUE ? 'c')
        AND VALUE->>'v' = '4'
      );
  END IF;

  COMMENT ON DOMAIN eql_v4.query_smallint_eq IS 'EQL smallint query operand (equality)';

  --! @brief Query-operand domain eql_v4.query_smallint_ord_ore (term-only; no `c`).
