        AND jsonb_typeof(VALUE -> 'lo') = 'string'
        AND left(VALUE ->> 'lo', 2) IN ('00', '01')
        AND jsonb_typeof(VALUE -> 'hi') = 'string'
        AND left(VALUE ->> 'hi', 2) IN ('00', '01')
